	}
	for _, p := range passes {
		dur, err := g.run(p, len(g.w))
		if err != nil {
			return nil, err
		}
		out.GPU += dur
		out.Passes++
		g.readRows(p, p.readouts, true, []map[int][]float32{out.Hidden})
		if len(p.states) > 0 && g.cache.fits(enc.StateLen) {
