const keyAlign = 64

// row appends one pass row and its metadata.
func (p *pass) row(q, e, cell int, branch bool, segStart, sLo, sHi, stateEnd int) {
	r := p.reqs[q]
	p.src = append(p.src, prow{q, e})
	b := uint32(0)
