package kev

import (
	"math"
	"testing"
)

// TestGPUBatchResidueByLayer (diagnostic): request A laid out alone, then
// behind a partner B, through the same batch planner, for the first L layers;
// the largest difference in A's residual rows after each L.
func TestGPUBatchResidueByLayer(t *testing.T) {
	g := loadGPU(t)
	e := loadEncoder(t)
	fx := loadFixtures(t)
	a := encodeFixture(t, e, fx[0].Request)
	b := encodeFixture(t, e, fx[3].Request)
	rowsOf := func(encs []*Encoding, layers int) [][]float32 {
		p, ok := g.planBatch(encs, make([]bool, len(encs)))
		if !ok {
			t.Fatal("does not fit one pass")
		}
		if _, err := g.run(p, layers); err != nil {
			t.Fatal(err)
		}
		q := len(encs) - 1
		out := make([][]float32, len(encs[q].IDs))
		for r, pr := range p.src {
			if pr.q == q {
				out[pr.e] = g.abuf.ReadFloat32At(int(g.aX)+r*g.Cfg.Hidden, g.Cfg.Hidden)
			}
		}
		return out
	}
	for L := 1; L <= len(g.w); L++ {
		alone := rowsOf([]*Encoding{a}, L)
		behind := rowsOf([]*Encoding{b, a}, L)
		worst, where, differ := 0.0, -1, 0
		for i := range alone {
			d := 0.0
			for j := range alone[i] {
				d = math.Max(d, math.Abs(float64(alone[i][j]-behind[i][j])))
			}
			if d > 0 {
				differ++
			}
			if d > worst {
				worst, where = d, i
			}
		}
		t.Logf("layers %2d (attn %v): %d of %d rows differ, max |dx| %.3e at row %d (state %d)", L, g.w[L-1].attn, differ, len(alone), worst, where, a.StateLen)
	}
}

