				if err != nil {
					if rows > 0 {
						break
					}
					t.Fatal(err)
				}
				for k := range probs {
					for _, v := range probs[k] {
						if math.IsNaN(v) {
							t.Errorf("%s (pass rows %d, hit %v): question %d is NaN", fx.Name, rows, p.CacheHit, k)
							break
						}
					}
				}
			}
		}
	}
}

