// TestGPUInProjRow78 (diagnostic): layer 4's in proj alone, with its input
// rows varied one way at a time; row 78's output against the plain run.
func TestGPUInProjRow78(t *testing.T) {
	g := loadGPU(t)
	e := loadEncoder(t)
	fx := loadFixtures(t)
	a := encodeFixture(t, e, fx[0].Request)
	const layer, row = 4, 78
	lda := g.Cfg.Hidden + gemmPad
	pn := g.w[layer].in.n
	p, _ := g.planBatch([]*Encoding{a}, []bool{false})
	d, labels := g.layerGraph(layer, p)
	t.Logf("dispatch 1 %q, n %d, rung %s", labels[1], p.n, q8For(p.n, pn).name)
	prep := func() {
		if _, err := g.run(p, layer); err != nil {
			t.Fatal(err)
		}
		if _, err := vk.DispatchMultiTimed(d[:1], 1, 1, true); err != nil {
			t.Fatal(err)
		}
	}
	proj := func() []float32 {
		if _, err := vk.DispatchMultiTimed(d[1:2], 1, 1, true); err != nil {
			t.Fatal(err)
		}
		return g.abuf.ReadFloat32At(int(g.aP)+row*pn, pn)
	}
	prep()
	hRow := g.hbuf.ReadUint16At(int(g.hA)+row*lda, lda)
	ref := proj()
	cmp := func(name string, got []float32) {
		n, w := 0, 0.0
		for i := range got {
			if got[i] != ref[i] {
				n++
				w = math.Max(w, math.Abs(float64(got[i]-ref[i])))
			}
		}
		t.Logf("%-34s %d of %d outputs differ, max %.3e", name, n, pn, w)
	}
	prep()
	cmp("again", proj())
	prep()
	g.hbuf.WriteUint16At(int(g.hA)+p.n*lda, make([]uint16, (128-p.n)*lda))
	cmp("pad rows zeroed", proj())
	prep()
	for r := 0; r < 128; r++ {
		if r != row {
			g.hbuf.WriteUint16At(int(g.hA)+r*lda, make([]uint16, lda))
		}
	}
	cmp("every other row zeroed", proj())
	prep()
	for r := 0; r < 128; r++ {
		g.hbuf.WriteUint16At(int(g.hA)+r*lda, hRow)
	}
	cmp("every row a copy of row 78", proj())
}
EOF
