// TestGPUInProjByShape (diagnostic): row 78's input in every row of the
// alone pass and of the batched pass; which rows' in proj outputs differ.
func TestGPUInProjByShape(t *testing.T) {
	g := loadGPU(t)
	e := loadEncoder(t)
	fx := loadFixtures(t)
	a := encodeFixture(t, e, fx[0].Request)
	b := encodeFixture(t, e, fx[3].Request)
	const layer, row = 4, 78
	lda := g.Cfg.Hidden + gemmPad
	pn := g.w[layer].in.n
	var hRow []uint16
	var ref []float32
	for _, encs := range [][]*Encoding{{a}, {b, a}} {
		p, _ := g.planBatch(encs, make([]bool, len(encs)))
		d, _ := g.layerGraph(layer, p)
		if _, err := g.run(p, layer); err != nil {
			t.Fatal(err)
		}
		if _, err := vk.DispatchMultiTimed(d[:1], 1, 1, true); err != nil {
			t.Fatal(err)
		}
		if hRow == nil {
			hRow = g.hbuf.ReadUint16At(int(g.hA)+row*lda, lda)
		}
