// TestGPUInProjSubmits (diagnostic): layer 4's in norm + in proj on the
// batched pass, in one submit and in two; A's row 78 against the alone run.
func TestGPUInProjSubmits(t *testing.T) {
	g := loadGPU(t)
	e := loadEncoder(t)
	fx := loadFixtures(t)
	a := encodeFixture(t, e, fx[0].Request)
	b := encodeFixture(t, e, fx[3].Request)
	const layer, row = 4, 78
	lda := g.Cfg.Hidden + gemmPad
	pn := g.w[layer].in.n
	get := func(encs []*Encoding, split bool) ([]uint16, []float32) {
		p, _ := g.planBatch(encs, make([]bool, len(encs)))
		r := row
		if len(encs) > 1 {
			r += len(encs[0].IDs)
		}
		d, _ := g.layerGraph(layer, p)
		if _, err := g.run(p, layer); err != nil {
			t.Fatal(err)
		}
		parts := [][]vk.MultiDispatch{d[:2]}
		if split {
			parts = [][]vk.MultiDispatch{d[:1], d[1:2]}
		}
		for _, part := range parts {
			if _, err := vk.DispatchMultiTimed(part, 1, 1, true); err != nil {
				t.Fatal(err)
			}
		}
		return g.hbuf.ReadUint16At(int(g.hA)+r*lda, lda), g.abuf.ReadFloat32At(int(g.aP)+r*pn, pn)
	}
	hRef, ref := get([]*Encoding{a}, false)
	for _, split := range []bool{false, true} {
		for _, encs := range [][]*Encoding{{a}, {b, a}} {
			h, o := get(encs, split)
			hd, od := 0, 0
			for i := 0; i < g.Cfg.Hidden; i++ {
				if h[i] != hRef[i] {
					hd++
				}
			}
			for i := range o {
				if o[i] != ref[i] {
					od++
				}
			}
			t.Logf("requests %d, split %v: input halves differing %d, outputs differing %d", len(encs), split, hd, od)
		}
	}
