// TestGPURepeatability (diagnostic): the same pass over and over, and
// between other passes; how often its residual rows change.
func TestGPURepeatability(t *testing.T) {
	g := loadGPU(t)
	e := loadEncoder(t)
	fx := loadFixtures(t)
	a := encodeFixture(t, e, fx[0].Request)
	b := encodeFixture(t, e, fx[3].Request)
	layers := len(g.w)
	if v := os.Getenv("KEV_LAYERS"); v != "" {
		layers, _ = strconv.Atoi(v)
	}
	rowsOf := func(encs []*Encoding) [][]float32 {
		p, _ := g.planBatch(encs, make([]bool, len(encs)))
		if _, err := g.run(p, layers); err != nil {
			t.Fatal(err)
		}
		q := len(encs) - 1
		out := make([][]float32, len(encs[q].IDs))
		for r, pr := range p.src {
			if pr.q == q {
				out[pr.e] = g.abuf.ReadFloat32At(int(g.aX)+r*g.Cfg.Hidden, g.Cfg.Hidden)
			}
		}
		return out
	}
	diff := func(x, y [][]float32) []int {
		var rows []int
		for i := range x {
			for j := range x[i] {
				if x[i][j] != y[i][j] {
					rows = append(rows, i)
					break
				}
			}
		}
		return rows
	}
	ref := rowsOf([]*Encoding{a})
	for i := 0; i < 10; i++ {
		if d := diff(ref, rowsOf([]*Encoding{a})); len(d) > 0 {
			t.Logf("alone, repeat %d: rows %v differ", i, d)
		}
	}
	for i := 0; i < 10; i++ {
		after := rowsOf([]*Encoding{b, a})
		d1 := diff(ref, after)
		d2 := diff(ref, rowsOf([]*Encoding{a}))
		if len(d1)+len(d2) > 0 {
			t.Logf("round %d: batched rows %v differ; alone after it, rows %v", i, d1, d2)
		}
	}
	t.Logf("done (%d layers)", layers)
}
EOF
