// TestGPUStaleVariants (diagnostic): alone after batched, with and without
// reading the batched pass back first.
func TestGPUStaleVariants(t *testing.T) {
	g := loadGPU(t)
	e := loadEncoder(t)
	fx := loadFixtures(t)
	a := encodeFixture(t, e, fx[0].Request)
	b := encodeFixture(t, e, fx[3].Request)
	run := func(encs []*Encoding) *pass {
		p, _ := g.planBatch(encs, make([]bool, len(encs)))
		if _, err := g.run(p, len(g.w)); err != nil {
			t.Fatal(err)
		}
		return p
	}
	read := func(p *pass) [][]float32 {
		out := make([][]float32, p.n)
		for r := range out {
			out[r] = g.abuf.ReadFloat32At(int(g.aX)+r*g.Cfg.Hidden, g.Cfg.Hidden)
		}
		return out
	}
	diff := func(x, y [][]float32) []int {
		var rows []int
		for i := range x {
			for j := range x[i] {
				if x[i][j] != y[i][j] {
					rows = append(rows, i)
					break
				}
			}
		}
		return rows
	}
	ref := read(run([]*Encoding{a}))
	for i := 0; i < 3; i++ {
		run([]*Encoding{b, a})
		t.Logf("batched, not read; then alone: %v", diff(ref, read(run([]*Encoding{a}))))
		read(run([]*Encoding{b, a}))
		t.Logf("batched, read;     then alone: %v", diff(ref, read(run([]*Encoding{a}))))
	}
}
