// TestGPUDirtyInProj (diagnostic): after a batched pass, the alone pass's
// layer-4 in proj on row 78, re-run with candidate regions cleared.
func TestGPUDirtyInProj(t *testing.T) {
	g := loadGPU(t)
	e := loadEncoder(t)
	fx := loadFixtures(t)
	a := encodeFixture(t, e, fx[0].Request)
	b := encodeFixture(t, e, fx[3].Request)
	const layer, row = 4, 78
	lda := g.Cfg.Hidden + gemmPad
	pn := g.w[layer].in.n
	pa, _ := g.planBatch([]*Encoding{a}, []bool{false})
	pb, _ := g.planBatch([]*Encoding{b, a}, []bool{false, false})
	d, _ := g.layerGraph(layer, pa)
	proj := func() []float32 {
		if _, err := vk.DispatchMultiTimed(d[1:2], 1, 1, true); err != nil {
			t.Fatal(err)
		}
		return g.abuf.ReadFloat32At(int(g.aP)+row*pn, pn)
	}
	prep := func(dirty bool) {
		if dirty {
			if _, err := g.run(pb, len(g.w)); err != nil {
				t.Fatal(err)
			}
		}
		if _, err := g.run(pa, layer); err != nil {
			t.Fatal(err)
		}
		if _, err := vk.DispatchMultiTimed(d[:1], 1, 1, true); err != nil {
			t.Fatal(err)
		}
	}
	prep(false)
	clean := proj()
	hClean := g.hbuf.ReadUint16At(int(g.hA)+row*lda, g.Cfg.Hidden)
	count := func(x []float32) int {
		n := 0
		for i := range x {
			if x[i] != clean[i] {
				n++
			}
		}
		return n
	}
	prep(true)
	hDirty := g.hbuf.ReadUint16At(int(g.hA)+row*lda, g.Cfg.Hidden)
	hd := 0
	for i := range hDirty {
		if hDirty[i] != hClean[i] {
			hd++
		}
	}
	t.Logf("dirty: input halves differing %d, outputs differing %d", hd, count(proj()))
	for _, c := range []struct {
		name string
		fn   func()
	}{
		{"hA rows >= n zeroed", func() { g.hbuf.ZeroUint16At(int(g.hA)+pa.n*lda, (g.rows-pa.n)*lda) }},
		{"hA rows != 78 zeroed", func() {
			g.hbuf.ZeroUint16At(int(g.hA), row*lda)
			g.hbuf.ZeroUint16At(int(g.hA)+(row+1)*lda, (g.rows-row-1)*lda)
		}},
		{"aP zeroed", func() { g.abuf.ZeroFloat32At(int(g.aP), g.rows*pn) }},
	} {
		prep(true)
		c.fn()
		t.Logf("dirty, %-22s outputs differing %d", c.name+":", count(proj()))
	}
}
EOF
go test ./kev/ -run TestGPUDirtyInProj -v -count=1 2>&1 | grep -E 'dirty|FAIL|panic'

